content:
:root {
  --primary-color: #3b82f6;
  --primary-light: #eff6ff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --border-color: #e5e7eb;
  --success-color: #10b981;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary-color: #3b82f6;
    --primary-light: #1e3a8a;
    --text-main: #f9fafb;
    --text-muted: #9ca3af;
    --bg-color: #111827;
    --card-bg: #1f2937;
    --border-color: #374151;
    --success-color: #34d399;
    --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.5), 0 2px 4px -1px rgba(0, 0, 0, 0.3);
  }
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.dashboard-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px;
}

.header {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}

@media (min-width: 768px) {
  .header {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.title {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-main);
}

.filter-container {
  display: flex;
  gap: 8px;
  background: var(--card-bg);
  padding: 4px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  width: fit-content;
}

.filter-btn {
  background: transparent;
  border: none;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.filter-btn:hover {
  color: var(--text-main);
  background-color: var(--bg-color);
}

.filter-btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.filter-btn.active {
  background-color: var(--primary-color);
  color: #ffffff;
}

.cards-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
  margin-bottom: 32px;
}

@media (min-width: 640px) {
  .cards-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .cards-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.card {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 1px solid var(--border-color);
  transition: transform 0.2s ease;
}

.card:hover {
  transform: translateY(-2px);
}

.card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-muted);
}

.card-value {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-main);
}

.card-change {
  font-size: 13px;
  font-weight: 600;
  color: var(--success-color);
  display: flex;
  align-items: center;
  gap: 4px;
}

.chart-section {
  background: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
}

.chart-title {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-main);
  margin-bottom: 20px;
}

.chart-container {
  width: 100%;
  height: 350px;
}

/**
 * 月ごとの売上・客数・平均単価のデータ構造
 */
export interface MonthlyData {
  /** 対象月（例: '1月'） */
  month: string;
  /** 売上金額（円） */
  sales: number;
  /** 客数（人） */
  customers: number;
  /** 平均単価（円） */
  avgPrice: number;
  /** 備考などのオプショナルプロパティ */
  note?: string;
}

/**
 * ダッシュボードの期間フィルター設定
 */
export interface FilterType {
  /** フィルターの種類を表すリテラル型 */
  type: 'all' | 'first_half' | 'second_half';
  /** フィルターの表示ラベル */
  label: string;
}

import { useState } from 'react';
import { MonthlyData, FilterType } from './types';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import './index.css';

const mockData: MonthlyData[] = [
  { month: '1月', sales: 1200000, customers: 3000, avgPrice: 40000 },
  { month: '2月', sales: 1100000, customers: 2800, avgPrice: 39285 },
  { month: '3月', sales: 1400000, customers: 3500, avgPrice: 40000 },
  { month: '4月', sales: 1300000, customers: 3200, avgPrice: 40625 },
  { month: '5月', sales: 1500000, customers: 3600, avgPrice: 41666 },
  { month: '6月', sales: 1600000, customers: 3800, avgPrice: 42105 },
  { month: '7月', sales: 1700000, customers: 4000, avgPrice: 42500 },
  { month: '8月', sales: 1800000, customers: 4200, avgPrice: 42857 },
  { month: '9月', sales: 1550000, customers: 3700, avgPrice: 41891 },
  { month: '10月', sales: 1650000, customers: 3900, avgPrice: 42307 },
  { month: '11月', sales: 1750000, customers: 4100, avgPrice: 42682 },
  { month: '12月', sales: 2000000, customers: 4500, avgPrice: 44444 },
];

const filters: FilterType[] = [
  { type: 'all', label: '全期間' },
  { type: 'first_half', label: '上半期' },
  { type: 'second_half', label: '下半期' },
];

const calculateGrowthRate = (current: number, previous: number): number => {
  if (!previous || previous === 0) return 0;
  return ((current - previous) / previous) * 100;
};

const formatGrowth = (rate: number): string => {
  const sign = rate > 0 ? '+' : '';
  return `${sign}${rate.toFixed(1)}%`;
};

export default function App() {
  const [currentFilter, setCurrentFilter] = useState<string>('all');

  const filteredData = mockData.filter((_, index) => {
    if (currentFilter === 'first_half') return index < 6;
    if (currentFilter === 'second_half') return index >= 6;
    return true;
  });

  const latestData = filteredData[filteredData.length - 1];

  let previousData: MonthlyData | null = null;
  if (latestData) {
    const originalIndex = mockData.findIndex((item) => item.month === latestData.month);
    if (originalIndex > 0) {
      previousData = mockData[originalIndex - 1];
    }
  }

  const salesGrowth = latestData && previousData ? calculateGrowthRate(latestData.sales, previousData.sales) : 0;
  const customersGrowth = latestData && previousData ? calculateGrowthRate(latestData.customers, previousData.customers) : 0;

  const currentAvgPrice = latestData ? latestData.sales / latestData.customers : 0;
  const previousAvgPrice = previousData ? previousData.sales / previousData.customers : 0;
  const avgPriceGrowth = previousAvgPrice ? calculateGrowthRate(currentAvgPrice, previousAvgPrice) : 0;

  return (
    <div className="dashboard-container">
      <header className="header">
        <h1 className="title">売上ダッシュボード</h1>
        <div className="filter-container">
          {filters.map((filter) => (
            <button
              key={filter.type}
              className={`filter-btn ${currentFilter === filter.type ? 'active' : ''}`}
              onClick={() => setCurrentFilter(filter.type)}
            >
              {filter.label}
            </button>
          ))}
        </div>
      </header>

      {filteredData.length === 0 ? (
        <div className="card" style={{ textAlign: 'center', padding: '48px' }}>
          <p className="card-title">データがありません</p>
        </div>
      ) : (
        <>
          <div className="cards-grid">
            <div className="card">
              <span className="card-title">売上</span>
              <span className="card-value">¥{latestData.sales.toLocaleString()}</span>
              <span className="card-change">
                {salesGrowth >= 0 ? '↑' : '↓'} 前月比 {formatGrowth(salesGrowth)}
              </span>
            </div>
            <div className="card">
              <span className="card-title">客数</span>
              <span className="card-value">{latestData.customers.toLocaleString()} 人</span>
              <span className="card-change">
                {customersGrowth >= 0 ? '↑' : '↓'} 前月比 {formatGrowth(customersGrowth)}
              </span>
            </div>
            <div className="card">
              <span className="card-title">平均単価</span>
              <span className="card-value">¥{Math.round(currentAvgPrice).toLocaleString()}</span>
              <span className="card-change">
                {avgPriceGrowth >= 0 ? '↑' : '↓'} 前月比 {formatGrowth(avgPriceGrowth)}
              </span>
            </div>
          </div>

          <section className="chart-section">
            <h2 className="chart-title">月別推移グラフ</h2>
            <div className="chart-container">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={filteredData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                  <XAxis dataKey="month" stroke="#6b7280" />
                  <YAxis yAxisId="left" stroke="#3b82f6" />
                  <YAxis yAxisId="right" orientation="right" stroke="#10b981" />
                  <Tooltip />
                  <Legend />
                  <Line
                    yAxisId="left"
                    type="monotone"
                    dataKey="sales"
                    name="売上 (円)"
                    stroke="#3b82f6"
                    strokeWidth={2}
                    activeDot={{ r: 8 }}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="customers"
                    name="客数 (人)"
                    stroke="#10b981"
                    strokeWidth={2}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </section>
        </>
      )}
    </div>
  );
}
